/* M17 (Apeverse 2.0): the ApePhone - home screen, apps reusing the game's menus with a way back, messages generated by the
   world (friends, gig + DJ reminders, festival nights, shop sales, rent, invitations), replies, calendar, bank, maps/GPS,
   journal, music, reef log, settings/backpack, persistence.   run_tests.ps1 -Suite tools/tests/suite_phone.js -Gpu [-Mobile] */
window.APE_T = (() => {
  const steps = [], step = (name, fn, o) => steps.push(Object.assign({ name, fn }, o || {}));
  const sleep = ms => new Promise(r => setTimeout(r, ms)), $ = id => document.getElementById(id);
  const until = async (cond, max) => { const t0 = Date.now(); while (Date.now() - t0 < (max || 8000)) { try { if (cond()) return true } catch (e) { } await sleep(120) } return false };
  const settled = () => AV.W && $('fade').style.opacity === '0';
  const go = async id => { AV.travel(id); return until(() => AV.W && AV.W.id === id && settled(), 180000) };
  const PH = () => AV.phone, txt = () => $('cmp').textContent, app = id => { const b = $('cmp').querySelector('[data-app="' + id + '"]'); b.click() };
  step('boot', async c => { $('gq').value = 'Medium'; $('bNew').click(); c('game starts', await until(() => AV.W && AV.running, 30000)); await sleep(1500); window.__realSave = window.__realSave || AV.save; AV.save = () => { }; AV.S.money = 3000; c('phone module', !!AV.phone) });
  step('Z opens the ApePhone home screen', async c => { AV.keymap.KeyZ(); await sleep(200); const ph = $('cmp').querySelector('.phone'); c('phone UI', !!ph); c('14+ apps (M16 adds Jobs)', $('cmp').querySelectorAll('[data-app]').length >= 14, $('cmp').querySelectorAll('[data-app]').length); c('status bar: time, weekday, credits, energy', /\d\d:\d\d/.test(txt()) && /3000/.test(txt()) && /⚡/.test(txt()), txt().slice(0, 60));
    c('fits the screen', ph.getBoundingClientRect().width <= innerWidth && ph.getBoundingClientRect().right <= innerWidth + 1, ph.getBoundingClientRect().width + ' / ' + innerWidth); c('touch 📱 button', !!$('tPh')) }, { shot: 'phone_home' });
  step('an app from the phone has a way back', async c => { app('contacts'); await sleep(200); c('contacts = the people panel', /People|Gente/.test(txt())); const b = $('cmp').querySelector('.phBack'); c('◀ Phone button', !!b); b.click(); await sleep(200); c('back on the home screen', !!$('cmp').querySelector('.phone [data-app]'));
    AV.closePanel('cmp'); AV.people.panel(); await sleep(150); c('opened outside the phone: no back button', !$('cmp').querySelector('.phBack')); AV.closePanel('cmp') });
  step('Madrid: friends + bookings text you', async c => { AV.S.time = 9 * 60; c('Madrid', await go('madrid')); await sleep(1500); PH().quiet = true; const S = AV.S, PE = AV.people; PE.mem('carmen').f = 40; PE.mem('carmen').met = 1; if (S.day % 2 !== 'carmen'.length % 2) S.day++;
    S.time = 20 * 60; c('Carmen texts (friend)', await until(() => S.phone.msgs.some(m => m.from === 'Carmen' && m.k.startsWith('fr:')), 6000), JSON.stringify(S.phone.msgs.map(m => m.k)));
    PE.mem('carmen').invite = { day: S.day, h: 21, place: 'bar' }; c('invitation reminder', await until(() => S.phone.msgs.some(m => m.k === 'inv:carmen:' + S.day), 4000));
    S.band = S.band || {}; S.band.members = ['kofi']; S.band.songs = [{ n: 'A', q: 50 }, { n: 'B', q: 50 }]; S.band.booked = null; S.time = 15 * 60; AV.gigs.bookGig(); S.time = 19 * 60 + 5; c('gig reminder at 19:00', await until(() => S.phone.msgs.some(m => m.k === 'gig:' + S.day), 4000));
    const n0 = S.phone.msgs.length; await sleep(2500); c('each message only once', S.phone.msgs.length === n0, n0 + ' → ' + S.phone.msgs.length); c('badge counts unread', PH().unread() >= 3 && /\d/.test(($('tPh') || {}).textContent || '0'), PH().unread()) });
  step('shop sales + rent texts', async c => { const S = AV.S, B = AV.biz; S.time = 12 * 60; B.rent('md_malasana'); const r = B.rec('md_malasana'); r.ledger.push({ d: S.day, a: 70, t: 'Sale' }, { d: S.day, a: 45, t: 'Sale' }); r.until = S.day + 1; S.day++; S.time = 10 * 60;
    c('yesterday\'s sales summary', await until(() => S.phone.msgs.some(m => m.k === 'biz:md_malasana:' + S.day && /115/.test(m.body)), 4000), (S.phone.msgs.find(m => m.k.startsWith('biz:')) || {}).body);
    AV.home.rent && AV.home.rent('md_pinar_2b'); const h = (S.homes || {}).md_pinar_2b; if (h) { h.until = S.day; await sleep(1500) } c('landlord: lease ends tonight', !h || S.phone.msgs.some(m => m.k === 'rent:md_pinar_2b:' + S.day), h ? 'rented' : 'no flat API') });
  step('Messages app: read a thread, reply (+friendship)', async c => { AV.keymap.KeyZ(); await sleep(150); app('msgs'); await sleep(200); c('inbox lists texts', /Carmen/.test(txt()) && $('cmp').querySelectorAll('[data-t]').length >= 3); const i = AV.S.phone.msgs.findIndex(m => m.from === 'Carmen'), f0 = AV.people.mem('carmen').f, u0 = PH().unread();
    $('cmp').querySelector('[data-t="' + i + '"]').click(); await sleep(200); c('thread open, marked read', AV.S.phone.msgs[i].read && PH().unread() === u0 - 1); $('cmp').querySelector('[data-r]').click(); await sleep(200); c('reply sent', !!AV.S.phone.msgs[i].reply); c('+1 friendship (once a day)', AV.people.mem('carmen').f === f0 + 1, f0 + '→' + AV.people.mem('carmen').f) }, { shot: 'phone_thread' });
  step('Calendar: gig, tapas, festivals, leases', async c => { AV.S.time = 12 * 60; c('a new gig booked (the old one was missed when the day passed)', AV.gigs.bookGig()); $('cmp').querySelector('[data-home]').click(); await sleep(150); app('cal'); await sleep(200); const t = txt(); c('your gig', /Your gig|Tu concierto/.test(t)); c('festival', /Hanging Bazaar|Sairee Fire Night/.test(t)); c('shop lease', /lease ends|alquiler/.test(t)); c('sorted by date', PH().lastCal.every((e, i, a) => !i || a[i - 1][0] <= e[0]), JSON.stringify(PH().lastCal.map(e => e[0]))) }, { shot: 'phone_calendar' });
  step('Bank: balance + transactions', async c => { $('cmp').querySelector('[data-home]').click(); await sleep(150); app('bank'); await sleep(200); c('balance', txt().includes(String(AV.S.money))); c('the shop rent shows as a payment', /−|-300|300/.test(txt()) && /Premises|Alquiler/.test(txt()), txt().slice(0, 160)) });
  step('Maps: places in this world -> GPS route', async c => { $('cmp').querySelector('[data-home]').click(); await sleep(150); app('maps'); await sleep(200); const n = $('cmp').querySelectorAll('[data-p]').length; c('places listed', n >= 5, n); $('cmp').querySelector('[data-p]').click(); await sleep(300); c('route set on the minimap', !!AV.minimap.dest && $('cmp').style.display === 'none') });
  step('Journal: tasks + milestones', async c => { AV.keymap.KeyZ(); await sleep(150); app('journal'); await sleep(200); const t = txt(); c('milestones', /Milestones|Hitos/.test(t) && /✅/.test(t) && /⬜/.test(t)); c('Madrid friends counted', /good friends|buenos amigos/.test(t)) }, { shot: 'phone_journal' });
  step('Reef log + Music + out-of-phone apps', async c => { $('cmp').querySelector('[data-home]').click(); await sleep(150); app('reef'); await sleep(150); c('reef log lists 7', $('cmp').querySelectorAll('.msg').length === 7); $('cmp').querySelector('[data-home]').click(); await sleep(150); app('music'); await sleep(150); c('music app', /Music|Música/.test(txt()));
    $('cmp').querySelector('[data-home]').click(); await sleep(150); app('bag'); await sleep(250); c('backpack opens', $('inv').style.display === 'block'); AV.closeTop(); AV.keymap.KeyZ(); await sleep(150); app('set'); await sleep(250); c('settings open', $('set').style.display === 'block'); AV.closeTop() });
  step('festival night text (Saturday)', async c => { const S = AV.S; while (AV.fest.weekday(S.day) !== 5) S.day++; S.time = 12 * 60 + 5; c('Hanging Bazaar text', await until(() => S.phone.msgs.some(m => m.k === 'fest:hanging_bazaar:' + S.day), 4000)) });
  step('persistence', async c => { const K = 'apeverse_test_phone', sv = window.__realSave, real = localStorage.getItem('apeverse_v09'); AV.saveKey = K; AV._bakFor = null; localStorage.removeItem(K); sv(); const L0 = AV.loadSave(), L = L0 && (L0.s || L0); localStorage.removeItem(K); localStorage.removeItem(K + '_bak'); AV.saveKey = 'apeverse_v09'; AV._bakFor = null;
    c('messages + replies saved', L && L.phone && L.phone.msgs.length >= 5 && L.phone.msgs.some(m => m.reply)); c("player's real save untouched", localStorage.getItem('apeverse_v09') === real) });
  step('no JS errors', async c => c('clean', !$('err').textContent, $('err').textContent));
  let active = steps;
  return { names() { active = steps; return steps.map(s => s.name) }, async exec(i) { const s = active[i], checks = [], c = (n, pass, d) => checks.push({ n: s.name + ': ' + n, pass: !!pass, d: d == null ? '' : String(d) }); try { await s.fn(c) } catch (e) { checks.push({ n: s.name + ': exception', pass: false, d: String(e && e.stack || e).slice(0, 400) }) } return { checks, shot: s.shot || null } } };
})();
